/**
 *
 * The useDnd hook creates a lightweight DnD coordinator for multi-container scenarios.
 *
 * @module useDnd
 * @group headless
 *
 */
import type { HeadlessInstance } from '@primereact/types/core';
/**
 * Sort event fired when items are reordered within a container.
 */
export interface UseDndSortEvent {
    containerId: unknown;
    fromIndex: number;
    toIndex: number;
}
/**
 * Transfer event fired when an item moves between containers.
 */
export interface UseDndTransferEvent {
    from: {
        containerId: unknown;
        index: number;
    };
    to: {
        containerId: unknown;
        index: number;
    };
}
/**
 * Defines valid properties in useDnd.
 */
export interface UseDndProps {
    /**
     * Callback fired when a sort occurs within a container.
     */
    onSort?: (event: UseDndSortEvent) => void;
    /**
     * Callback fired when an item transfers between containers.
     */
    onTransfer?: (event: UseDndTransferEvent) => void;
}
/**
 * Defines valid state in useDnd.
 */
export interface UseDndState {
    /**
     * Whether a drag operation is in progress.
     */
    dragging: boolean;
}
/**
 * Data attribute props for the DnD root element.
 */
export interface UseDndRootProps {
    'data-scope': string;
    'data-part': string;
    'data-dragging'?: string;
}
/**
 * Defines the methods and properties exposed by useDnd.
 */
export interface UseDndExposes {
    /**
     * The reactive DnD state.
     */
    state: UseDndState;
    /**
     * The DnD coordinator instance. Pass this to useSortableContainer.
     */
    dnd: unknown;
    /**
     * Pre-built data attribute props for the root container.
     */
    rootProps: UseDndRootProps;
}
/**
 * Instance of useDnd headless.
 */
export type UseDndInstance = HeadlessInstance<UseDndProps, UseDndState, UseDndExposes>;
